import sys, json, random, subprocess
sys.path.insert(0, "/app/tmp/t")
from run import run_json
import ref

MAXN = 4611686018427387903
LEVELS = ["I", "H", "Z", "A"]
FRAMES = ["PADDING", "PING", "ACK", "CRYPTO", "STREAM", "RESET_STREAM", "STOP_SENDING",
          "CLOSE", "HANDSHAKE_DONE", "UNKNOWN"]

def rhex(rng, n=None):
    if n is None:
        n = rng.randint(0, 8)
    return "".join(rng.choice("0123456789abcdef") for _ in range(2 * n))

def rframe(rng):
    ty = rng.choice(FRAMES)
    if ty == "PADDING" or ty == "PING" or ty == "HANDSHAKE_DONE" or ty == "UNKNOWN":
        return {"type": ty}
    if ty == "ACK":
        n = rng.randint(0, 3)
        ranges = []
        for _ in range(n):
            a = rng.randint(0, 30); b = rng.randint(0, 30)
            ranges.append([min(a, b), max(a, b)] if rng.random() < 0.7 else [a, b])
        return {"type": "ACK", "ranges": ranges}
    if ty == "CRYPTO":
        return {"type": "CRYPTO", "offset": rng.randint(0, 12), "data_hex": rhex(rng)}
    if ty == "STREAM":
        return {"type": "STREAM", "id": rng.choice([0, 2, 4, 6, 8, 1, 3, 12, 10]),
                "offset": rng.randint(0, 10), "data_hex": rhex(rng),
                "fin": rng.random() < 0.4}
    if ty == "RESET_STREAM":
        return {"type": "RESET_STREAM", "id": rng.choice([0, 2, 4, 6, 8, 1, 3]),
                "final_size": rng.randint(0, 12)}
    if ty == "STOP_SENDING":
        return {"type": "STOP_SENDING", "id": rng.choice([0, 4, 8, 2, 1])}
    if ty == "CLOSE":
        return {"type": "CLOSE", "app": rng.random() < 0.5, "code": rng.randint(0, 100)}
    raise AssertionError

def rpkt(rng):
    return {"level": rng.choice(LEVELS), "pn": rng.randint(0, 3),
            "auth": rng.random() < 0.85,
            "frames": [rframe(rng) for _ in range(rng.randint(0, 4))]}

def rcfg(rng):
    return {
        "early": rng.random() < 0.5,
        "overlap": rng.choice(["reject", "first"]),
        "buffer_packets": rng.randint(0, 4),
        "idle_ms": rng.choice([0, 0, 5, 10, 20]),
        "max_streams_bidi": rng.randint(0, 4),
        "max_streams_uni": rng.randint(0, 4),
        "max_stream_data": rng.randint(0, 16),
        "max_data": rng.randint(0, 40),
        "crypto_limit": rng.randint(0, 16),
        "sent": {"I": mkranges(rng), "H": mkranges(rng), "A": mkranges(rng)},
    }

def mkranges(rng):
    n = rng.randint(0, 3)
    out = []
    cur = 0
    for _ in range(n):
        lo = cur + rng.randint(0, 5)
        hi = lo + rng.randint(0, 6)
        out.append([lo, hi])
        cur = hi + 2
    return out

def revent(rng, t):
    op = rng.choices(["datagram", "key", "tick"], weights=[6, 3, 1])[0]
    if op == "tick":
        return {"t": t, "op": "tick"}
    if op == "key":
        return {"t": t, "op": "key", "level": rng.choice(LEVELS),
                "action": rng.choice(["install", "discard"])}
    return {"t": t, "op": "datagram", "bytes": rng.choice([1200, 1200, 1200, 1199, 100, 65535]),
            "packets": [rpkt(rng) for _ in range(rng.randint(1, 4))]}

def rtrace(rng, tid):
    cfg = rcfg(rng)
    events = []
    t = 0
    for _ in range(rng.randint(0, 12)):
        t += rng.choice([0, 0, 1, 2, 3, 5, 10, 15])
        events.append(revent(rng, t))
    return {"id": tid, "config": cfg, "events": events}

def main():
    seed0 = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    n = int(sys.argv[2]) if len(sys.argv) > 2 else 300
    bad = 0
    for i in range(n):
        rng = random.Random(seed0 + i)
        ntr = rng.randint(1, 3)
        doc = {"version": 1, "traces": [rtrace(rng, "t%d" % k) for k in range(ntr)]}
        rc, out, err = run_json(doc)
        if rc != 0:
            print("RC!=0 seed", seed0 + i, err[:200]); bad += 1; continue
        got = json.loads(out)
        want = ref.run(doc)
        if got != want:
            bad += 1
            print("MISMATCH seed", seed0 + i)
            print("input:", json.dumps(doc))
            for g, w in zip(got["results"], want["results"]):
                if g != w:
                    print(" got:", json.dumps(g))
                    print(" want:", json.dumps(w))
            if bad >= 3:
                break
    print("done, mismatches:", bad, "of", n)

main()
PYEOF
